import test from 'node:test';
import assert from 'node:assert/strict';
import { statement } from '../src/statements.js';
import { createInvoice, issueInvoice } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';

test('statement includes issued invoices for customer', () => {
  const inv1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(inv1.ok, true);

  const issued1 = issueInvoice(inv1.value, []);
  assert.equal(issued1.ok, true);

  const result = statement('C-002', [issued1.value], '2026-10-10');
  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 1);
  assert.equal(result.value.invoices[0].number, issued1.value.number);
});

test('statement excludes draft invoices', () => {
  const draft = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(draft.ok, true);

  const result = statement('C-002', [draft.value], '2026-10-10');
  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 0);
});

test('statement excludes invoices with issueDate after asOf', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(inv.ok, true);

  const issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);

  const result = statement('C-002', [issued.value], '2026-10-10');
  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 0);
});

test('statement includes invoices with issueDate equal to asOf', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-10',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(inv.ok, true);

  const issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);

  const result = statement('C-002', [issued.value], '2026-10-10');
  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 1);
});

test('statement includes partially_paid invoices', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  assert.equal(inv.ok, true);

  const issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);

  const paid = recordPayment(issued.value, { amount: 20000, date: '2026-10-09' });
  assert.equal(paid.ok, true);

  const result = statement('C-002', [paid.value], '2026-10-10');
  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 1);
  assert.equal(result.value.invoices[0].status, undefined);
});

test('statement excludes paid invoices', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  assert.equal(inv.ok, true);

  let issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);

  const totals = require('../src/invoices.js').invoiceTotals(issued.value);
  const paid = recordPayment(issued.value, { amount: totals.total, date: '2026-10-09' });
  assert.equal(paid.ok, true);

  const result = statement('C-002', [paid.value], '2026-10-10');
  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 0);
});

test('statement returns invoice details with total and due', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(inv.ok, true);

  const issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);

  const result = statement('C-002', [issued.value], '2026-10-10');
  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 1);

  const invDetail = result.value.invoices[0];
  assert.equal(invDetail.number, issued.value.number);
  assert.equal(invDetail.issueDate, '2026-10-07');
  assert.equal(invDetail.dueDate, issued.value.dueDate);
  assert.equal(typeof invDetail.total, 'number');
  assert.equal(typeof invDetail.due, 'number');
  assert.equal(invDetail.due, invDetail.total);
});

test('statement calculates due correctly with partial payment', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  assert.equal(inv.ok, true);

  let issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);

  const paid = recordPayment(issued.value, { amount: 20000, date: '2026-10-09' });
  assert.equal(paid.ok, true);

  const { invoiceTotals } = require('../src/invoices.js');
  const totals = invoiceTotals(issued.value);

  const result = statement('C-002', [paid.value], '2026-10-10');
  assert.equal(result.ok, true);
  assert.equal(result.value.invoices[0].due, totals.total - 20000);
});

test('statement sorts invoices by issueDate', () => {
  const inv1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(inv1.ok, true);
  const issued1 = issueInvoice(inv1.value, []);
  assert.equal(issued1.ok, true);

  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(inv2.ok, true);
  const issued2 = issueInvoice(inv2.value, []);
  assert.equal(issued2.ok, true);

  const inv3 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-10',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(inv3.ok, true);
  const issued3 = issueInvoice(inv3.value, []);
  assert.equal(issued3.ok, true);

  const result = statement('C-002', [issued1.value, issued2.value, issued3.value], '2026-10-20');
  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 3);
  assert.equal(result.value.invoices[0].issueDate, '2026-10-07');
  assert.equal(result.value.invoices[1].issueDate, '2026-10-10');
  assert.equal(result.value.invoices[2].issueDate, '2026-10-15');
});

test('statement returns CUSTOMER_NOT_FOUND for unknown customer', () => {
  const result = statement('C-999', [], '2026-10-10');
  assert.deepEqual(result, { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('statement normalizes customer ID', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(inv.ok, true);

  const issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);

  const result = statement('c-002 ', [issued.value], '2026-10-10');
  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-002');
  assert.equal(result.value.invoices.length, 1);
});

test('statement calculates totalDue as sum of all due amounts', () => {
  const inv1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(inv1.ok, true);
  const issued1 = issueInvoice(inv1.value, []);
  assert.equal(issued1.ok, true);

  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  assert.equal(inv2.ok, true);
  let issued2 = issueInvoice(inv2.value, []);
  assert.equal(issued2.ok, true);

  const paid2 = recordPayment(issued2.value, { amount: 20000, date: '2026-10-09' });
  assert.equal(paid2.ok, true);

  const result = statement('C-002', [issued1.value, paid2.value], '2026-10-10');
  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 2);

  const expectedTotalDue = result.value.invoices.reduce((sum, inv) => sum + inv.due, 0);
  assert.equal(result.value.totalDue, expectedTotalDue);
});

test('statement returns empty list for customer with no outstanding invoices', () => {
  const result = statement('C-002', [], '2026-10-10');
  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 0);
  assert.equal(result.value.totalDue, 0);
});

test('statement filters by customer only', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(inv1.ok, true);
  const issued1 = issueInvoice(inv1.value, []);
  assert.equal(issued1.ok, true);

  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(inv2.ok, true);
  const issued2 = issueInvoice(inv2.value, []);
  assert.equal(issued2.ok, true);

  const result = statement('C-002', [issued1.value, issued2.value], '2026-10-10');
  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 1);
  assert.equal(result.value.invoices[0].number, issued2.value.number);
});

test('statement includes invoices with different totals and dues', () => {
  const inv1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(inv1.ok, true);
  const issued1 = issueInvoice(inv1.value, []);
  assert.equal(issued1.ok, true);

  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  assert.equal(inv2.ok, true);
  const issued2 = issueInvoice(inv2.value, []);
  assert.equal(issued2.ok, true);

  const result = statement('C-002', [issued1.value, issued2.value], '2026-10-10');
  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 2);
  assert(result.value.invoices[0].total !== result.value.invoices[1].total);
  assert(result.value.invoices[0].due !== result.value.invoices[1].due);
});

