test('statement calculates totalDue as sum of all due amounts', () => {
  const inv1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(inv1.ok, true);
  const issued1 = issueInvoice(inv1.value, []);
  assert.equal(issued1.ok, true);

  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  assert.equal(inv2.ok, true);
  let issued2 = issueInvoice(inv2.value, []);
  assert.equal(issued2.ok, true);

  const paid2 = recordPayment(issued2.value, { amount: 20000, date: '2026-10-09' });
  assert.equal(paid2.ok, true);

  const result = statement('C-002', [issued1.value, paid2.value], '2026-10-10');
  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 2);

  const expectedTotalDue = result.value.invoices.reduce((sum, inv) => sum + inv.due, 0);
  assert.equal(result.value.totalDue, expectedTotalDue);
});

